mapper.select:
select session_id
from sessions
where created_by_user_id=#{userId}
  and batch_mode=true
  and batch_item_request_id=#{itemRequestId}
limit 1

mapper.update:
update sessions
set batch_mode=true,
    batch_id=#{batchId},
    batch_item_request_id=#{itemRequestId}
where session_id=#{sessionId}
  and created_by_user_id=#{userId}
  and batch_mode=false
  and batch_id is null
  and batch_item_request_id is null
